using System.ComponentModel.DataAnnotations;
using CommunityToolkit.Mvvm.ComponentModel;

namespace Darp.MvvmValidator.Tests;

public partial class RegistrationViewModel : ValidatingObservableObject
{
    [ObservableProperty]
    [Required]
    [StringLength(20, MinimumLength = 3)]
    [Display(Name = "User name")]
    private string? _userName;

    [ObservableProperty]
    [Required]
    [EmailAddress]
    public partial string? Email { get; set; }

    [ObservableProperty]
    [Required]
    private string? _password;

    // nameof() of a property generated by [ObservableProperty]
    [ObservableProperty]
    [property: Compare(nameof(Password))]
    private string? _confirmPassword;

    [Range(18, 120)]
    public int Age
    {
        get;
        set => SetProperty(ref field, value);
    } = 18;

    [CustomValidation(typeof(RegistrationViewModel), nameof(ValidateNickname))]
    public string? Nickname
    {
        get;
        set => SetProperty(ref field, value);
    }

    public Func<string?, ValidationResult?>? NicknameCallback { get; set; }

    public new void ValidateAllProperties() => base.ValidateAllProperties();

    public new void ValidateProperty(string propertyName) => base.ValidateProperty(propertyName);

    public new void SetErrors(string propertyName, IEnumerable<ValidationResult> errors) =>
        base.SetErrors(propertyName, errors);

    public new void ClearErrors() => base.ClearErrors();

    public static ValidationResult? ValidateNickname(string? nickname, ValidationContext context)
    {
        ArgumentNullException.ThrowIfNull(context);
        var instance = (RegistrationViewModel)context.ObjectInstance;
        return instance.NicknameCallback?.Invoke(nickname);
    }
}

public partial class AddressViewModel : RegistrationViewModel
{
    [ObservableProperty]
    [Required]
    private string? _street;
}

public partial class Outer
{
    public partial class GenericViewModel<T> : ValidatingObservableObject
    {
        [ObservableProperty]
        [Required]
        private T? _value;
    }
}
